off_t pos = 0;
size_t left = st.st_size;        // 3 GiB file
while (left > 0) {
    ssize_t n = sendfile(sock, fd, &pos, left);
    if (n == -1) {
        if (errno == EAGAIN) { wait_writable(sock); continue; }
        if (errno == EINVAL || errno == ENOSYS)
            return copy_with_read_write(sock, fd, pos, left);
        return -1;
    }
    left -= n;                   // short transfers are normal
}

