void reap_completions(int fd) {
    for (;;) {
        if (recvmsg(fd, &msg, MSG_ERRQUEUE) == -1)
            return;              // EAGAIN: queue empty
        serr = (void *)CMSG_DATA(CMSG_FIRSTHDR(&msg));
        if (serr->ee_origin != SO_EE_ORIGIN_ZEROCOPY)
            continue;
        uint32_t lo = serr->ee_info, hi = serr->ee_data;
        if (serr->ee_code & SO_EE_CODE_ZEROCOPY_COPIED)
            copied_sends += hi - lo + 1;
        for (uint32_t id = lo; id != hi + 1; id++)
            release_buffer(id);  // safe to reuse now
    }
}
